1	package cli
2	
3	import (
4		"bufio"
5		"context"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"os/exec"
11		"strconv"
12		"strings"
13		"sync"
14	)
15	
16	// git_catfile_batch.go routes repeated object reads through one long-lived
17	// `git cat-file --batch` child per (gitDir, policy) instead of one `git
18	// cat-file` exec per blob. A cold export/distill on a ~1,000-checkpoint repo
19	// spawned ~5,000 git processes at ~30ms each (COR-2182); the same reads
20	// through one child are pipe round-trips.
21	//
22	// The child carries the exact policy of the per-exec path it replaces: the
23	// hardened git args every spawn gets, the repository filter-driver overrides,
24	// and GIT_NO_LAZY_FETCH=1 when the caller demanded a local-only read. Callers
25	// treat any infrastructure error as "fall back to the per-exec path", so a
26	// broken or killed child never changes behavior, only speed.
27	//
28	// Children exit on stdin EOF, which the OS delivers when this process exits.
29	// A long-lived parent (the MCP server) keeps at most one idle child per git
30	// dir and policy, which is bounded by the handful of repositories it serves.
31	
32	// catFileBatchMaxBlobBytes bounds one blob read so a corrupt size header
33	// cannot drive the process out of memory. The per-exec path buffered whole
34	// blobs too; this is a guard against a nonsense header, not a content policy.
35	const catFileBatchMaxBlobBytes = 1 << 30
36	
37	// errCatFileBatchMissing is git's definitive "object not found" answer. It is
38	// a real result, not an infrastructure failure: callers must NOT retry it on
39	// the per-exec path, which would answer the same thing one spawn later.
40	var errCatFileBatchMissing = errors.New("object missing")
41	
42	type catFileBatchKey struct {
43		gitDir    string
44		localOnly bool
45		check     bool
46	}
47	
48	// catFileBatchProc is one child. Requests are strictly serialized under mu:
49	// one spec line written, one full record read, so the stream cannot desync
50	// across goroutines. Any read/parse irregularity marks the child broken and
51	// kills it; the registry replaces it on the next request.
52	type catFileBatchProc struct {
53		mu     sync.Mutex
54		cmd    *exec.Cmd
55		in     io.WriteCloser
56		out    *bufio.Reader
57		broken bool
58	}
59	
60	var (
61		catFileBatchMu    sync.Mutex
62		catFileBatchProcs = map[catFileBatchKey]*catFileBatchProc{}
63	)
64	
65	func commandRunnerIsExec(runner CommandRunner) bool {
66		switch runner.(type) {
67		case ExecRunner, *ExecRunner:
68			return true
69		}
70		return false
71	}
72	
73	func catFileBatchProcFor(ctx context.Context, key catFileBatchKey) (*catFileBatchProc, error) {
74		catFileBatchMu.Lock()
75		defer catFileBatchMu.Unlock()
76		if p, ok := catFileBatchProcs[key]; ok {
77			return p, nil
78		}
79		mode := "--batch"
80		if key.check {
81			mode = "--batch-check"
82		}
83		args := hardenedGitArgs("cat-file", mode)
84		overrides, err := repoFilterDriverOverrides(ctx, key.gitDir)
85		if err != nil {
86			return nil, err
87		}
88		var env map[string]string
89		if key.localOnly {
90			env = map[string]string{gitNoLazyFetchEnv: "1"}
91		}
92		// Not CommandContext: the child outlives any one caller's context on
93		// purpose. It dies on stdin EOF when this process exits.
94		cmd := exec.Command("git", args...)
95		cmd.Dir = key.gitDir
96		cmd.Env = gitConfigOverrideEnv(mergeCommandEnv(os.Environ(), env), overrides)
97		in, err := cmd.StdinPipe()
98		if err != nil {
99			return nil, err
100		}
101		out, err := cmd.StdoutPipe()
102		if err != nil {
103			return nil, err
104		}
105		if err := cmd.Start(); err != nil {
106			return nil, err
107		}
108		p := &catFileBatchProc{cmd: cmd, in: in, out: bufio.NewReader(out)}
109		catFileBatchProcs[key] = p
110		return p, nil
111	}
112	
113	func catFileBatchDrop(key catFileBatchKey, p *catFileBatchProc) {
114		catFileBatchMu.Lock()
115		if catFileBatchProcs[key] == p {
116			delete(catFileBatchProcs, key)
117		}
118		catFileBatchMu.Unlock()
119	}
120	
121	func (p *catFileBatchProc) fail() {
122		p.broken = true
123		_ = p.in.Close()
124		if p.cmd.Process != nil {
125			_ = p.cmd.Process.Kill()
126		}
127		// Reap the child so a failed proc never lingers as a zombie.
128		go func() { _ = p.cmd.Wait() }()
129	}
130	
131	// request writes one spec and reads one record. body is nil in check mode.
132	// ponytail: no mid-read context cancellation — local object reads are pipe
133	// round-trips and the child dies with the parent; a hung git would require
134	// killing the child, which the broken path already does on the next error.
135	func (p *catFileBatchProc) request(ctx context.Context, spec string, withBody bool) ([]byte, string, error) {
136		if err := ctx.Err(); err != nil {
137			return nil, "", err
138		}
139		if strings.ContainsAny(spec, "\n\r") {
140			return nil, "", fmt.Errorf("git cat-file batch: spec contains a newline: %q", spec)
141		}
142		p.mu.Lock()
143		defer p.mu.Unlock()
144		if p.broken {
145			return nil, "", errors.New("git cat-file batch: process is broken")
146		}
147		fail := func(err error) ([]byte, string, error) {
148			p.fail()
149			return nil, "", err
150		}
151		if _, err := io.WriteString(p.in, spec+"\n"); err != nil {
152			return fail(fmt.Errorf("git cat-file batch: write request: %w", err))
153		}
154		header, err := p.out.ReadString('\n')
155		if err != nil {
156			return fail(fmt.Errorf("git cat-file batch: read header: %w", err))
157		}
158		fields := strings.Fields(header)
159		if len(fields) == 2 {
160			// "<spec> missing" and friends ("ambiguous") are answers from a
161			// healthy child, not failures.
162			return nil, "", fmt.Errorf("git cat-file batch: %s %s: %w", spec, fields[1], errCatFileBatchMissing)
163		}
164		if len(fields) != 3 {
165			return fail(fmt.Errorf("git cat-file batch: unexpected header %q for %s", strings.TrimSpace(header), spec))
166		}
167		objType := fields[1]
168		size, err := strconv.ParseInt(fields[2], 10, 64)
169		if err != nil || size < 0 {
170			return fail(fmt.Errorf("git cat-file batch: unparseable size in header %q", strings.TrimSpace(header)))
171		}
172		if !withBody {
173			return nil, objType, nil
174		}
175		if size > catFileBatchMaxBlobBytes {
176			// Drain the record (content + trailing LF) to keep the stream in
177			// sync, then refuse the read.
178			if _, err := io.CopyN(io.Discard, p.out, size+1); err != nil {
179				return fail(fmt.Errorf("git cat-file batch: drain oversized %s: %w", spec, err))
180			}
181			return nil, "", fmt.Errorf("git cat-file batch: %s is %d bytes, over the %d byte guard", spec, size, catFileBatchMaxBlobBytes)
182		}
183		body := make([]byte, size)
184		if _, err := io.ReadFull(p.out, body); err != nil {
185			return fail(fmt.Errorf("git cat-file batch: read %d-byte body for %s: %w", size, spec, err))
186		}
187		// Every record ends with one LF after the content.
188		if trailer, err := p.out.ReadByte(); err != nil || trailer != '\n' {
189			return fail(fmt.Errorf("git cat-file batch: record for %s not terminated by LF", spec))
190		}
191		return body, objType, nil
192	}
193	
194	func catFileBatchRequest(ctx context.Context, gitDir, spec string, localOnly, check bool) ([]byte, string, error) {
195		key := catFileBatchKey{gitDir: gitDir, localOnly: localOnly, check: check}
196		p, err := catFileBatchProcFor(ctx, key)
197		if err != nil {
198			return nil, "", err
199		}
200		body, objType, err := p.request(ctx, spec, !check)
201		if err != nil && p.broken {
202			catFileBatchDrop(key, p)
203		}
204		return body, objType, err
205	}
206	
207	// catFileBatchRead reads one object's content: `git cat-file -p <spec>`, batched.
208	func catFileBatchRead(ctx context.Context, gitDir, spec string, localOnly bool) ([]byte, error) {
209		body, _, err := catFileBatchRequest(ctx, gitDir, spec, localOnly, false)
210		return body, err
211	}
212	
213	// catFileBatchType reports one object's type: `git cat-file -t <spec>`, batched.
214	func catFileBatchType(ctx context.Context, gitDir, spec string, localOnly bool) (string, error) {
215		_, objType, err := catFileBatchRequest(ctx, gitDir, spec, localOnly, true)
216		return objType, err
217	}
218	
219	// localObjectType answers `git cat-file -t` under the local-only policy,
220	// batched for the production runner and per-exec for every other runner.
221	// A batch "missing" answer is definitive; other batch errors fall back.
222	func localObjectType(ctx context.Context, runner CommandRunner, gitDir, spec string) (string, error) {
223		if commandRunnerIsExec(runner) {
224			objType, err := catFileBatchType(ctx, gitDir, spec, true)
225			if err == nil || errors.Is(err, errCatFileBatchMissing) {
226				return objType, err
227			}
228		}
229		kind, _, err := runCheckpointGitLocal(ctx, runner, gitDir, "cat-file", "-t", spec)
230		if err != nil {
231			return "", err
232		}
233		return strings.TrimSpace(string(kind)), nil
234	}
