1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"fmt"
7		"io"
8		"os"
9		"os/exec"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// CommandRunner runs external commands. Tests replace it so export behavior
16	// can be verified without requiring a real Entire checkout.
17	type CommandRunner interface {
18		Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error)
19	}
20	
21	// EnvironmentCommandRunner is the narrow capability used when a child process
22	// needs an operation-specific environment safety boundary. Keeping it optional
23	// avoids making every test runner and provider adapter environment-aware while
24	// still letting security-sensitive callers fail closed when the capability is
25	// unavailable.
26	type EnvironmentCommandRunner interface {
27		RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error)
28	}
29	
30	// CommandStreamer is an optional capability for CommandRunner implementations
31	// that can expose a child process's stdout incrementally instead of buffering
32	// the entire output. The semantic provider snapshot can grow to hundreds of
33	// megabytes on large repositories, so the indexer streams it record-by-record
34	// rather than holding it all in memory. Runners that do not implement this
35	// interface fall back to the buffered Run path.
36	type CommandStreamer interface {
37		Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error)
38	}
39	
40	// CommandStream is a started command whose stdout is consumed incrementally.
41	// Callers must read Stdout to completion (or drain it) before calling Wait.
42	type CommandStream interface {
43		// Stdout returns the live stdout reader.
44		Stdout() io.Reader
45		// Wait blocks until the command exits, returning the captured stderr and
46		// the raw exit error (unwrapped, so callers can format it).
47		Wait() (stderr []byte, err error)
48		// Close releases any resources. It is safe to call after Wait.
49		Close() error
50	}
51	
52	// streamStderrCap bounds how much stderr a streamed command may retain in
53	// memory. Provider stderr is only used for diagnostics, so a generous cap keeps
54	// error messages useful without letting a misbehaving provider exhaust memory.
55	const streamStderrCap = 256 * 1024
56	
57	// commandWaitDelay bounds how long a command may keep the runner blocked after
58	// its context is cancelled.
59	//
60	// exec.CommandContext kills the child on cancellation, but cmd.Run and cmd.Wait
61	// return only once every writer of the stdout/stderr pipes has closed. A child
62	// that spawns a grandchild inheriting those descriptors therefore keeps the
63	// runner blocked for as long as the GRANDCHILD lives, long after the deadline
64	// passed and the child was killed. Every context deadline in this binary is
65	// implemented on top of this runner, so without a WaitDelay a single stray
66	// grandchild makes all of them unenforceable: measured at 30s of wait against a
67	// 300ms deadline.
68	//
69	// WaitDelay bounds waiting for process exit and inherited pipes after
70	// cancellation. CommandContext kills the direct child, not its process group. It is a
71	// backstop, not a timeout: a command that exits normally is never affected, and
72	// the delay only starts counting once the context is already cancelled.
73	const commandWaitDelay = 2 * time.Second
74	
75	type ExecRunner struct{}
76	
77	func (ExecRunner) Run(ctx context.Context, dir, name string, args ...string) ([]byte, []byte, error) {
78		return runExecCommand(ctx, dir, nil, name, args...)
79	}
80	
81	func (ExecRunner) RunWithEnv(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
82		return runExecCommand(ctx, dir, env, name, args...)
83	}
84	
85	func runExecCommand(ctx context.Context, dir string, env map[string]string, name string, args ...string) ([]byte, []byte, error) {
86		var gitOverrides []gitConfigOverride
87		if name == "git" {
88			args = hardenedGitArgs(args...)
89			// The filter neutralizers travel in the environment, not in argv; see
90			// git_harden_filters.go for why `-c` cannot express them safely.
91			var err error
92			gitOverrides, err = repoFilterDriverOverrides(ctx, dir)
93			if err != nil {
94				return nil, nil, err
95			}
96		}
97		cmd := exec.CommandContext(ctx, name, args...)
98		cmd.WaitDelay = commandWaitDelay
99		if dir != "" {
100			cmd.Dir = dir
101		}
102		if len(env) > 0 || len(gitOverrides) > 0 {
103			cmd.Env = gitConfigOverrideEnv(mergeCommandEnv(os.Environ(), env), gitOverrides)
104		}
105	
106		var stdout bytes.Buffer
107		var stderr bytes.Buffer
108		cmd.Stdout = &stdout
109		cmd.Stderr = &stderr
110	
111		err := cmd.Run()
112		if err != nil {
113			if stderr.Len() > 0 {
114				return stdout.Bytes(), stderr.Bytes(), fmt.Errorf("%s %v: %w: %s", name, args, err, stderr.String())
115			}
116			return stdout.Bytes(), stderr.Bytes(), fmt.Errorf("%s %v: %w", name, args, err)
117		}
118		return stdout.Bytes(), stderr.Bytes(), nil
119	}
120	
121	func mergeCommandEnv(base []string, overrides map[string]string) []string {
122		out := make([]string, 0, len(base)+len(overrides))
123		for _, entry := range base {
124			key, _, ok := strings.Cut(entry, "=")
125			if ok {
126				if _, replaced := overrides[key]; replaced {
127					continue
128				}
129			}
130			out = append(out, entry)
131		}
132		keys := make([]string, 0, len(overrides))
133		for key := range overrides {
134			keys = append(keys, key)
135		}
136		sort.Strings(keys)
137		for _, key := range keys {
138			value := overrides[key]
139			out = append(out, key+"="+value)
140		}
141		return out
142	}
143	
144	// Stream starts name and exposes its stdout as a streaming reader. stderr is
145	// captured into a bounded buffer by exec's own copy goroutine, so reading
146	// stdout never blocks on stderr.
147	func (ExecRunner) Stream(ctx context.Context, dir, name string, args ...string) (CommandStream, error) {
148		var gitOverrides []gitConfigOverride
149		if name == "git" {
150			args = hardenedGitArgs(args...)
151			var err error
152			gitOverrides, err = repoFilterDriverOverrides(ctx, dir)
153			if err != nil {
154				return nil, err
155			}
156		}
157		cmd := exec.CommandContext(ctx, name, args...)
158		cmd.WaitDelay = commandWaitDelay
159		if dir != "" {
160			cmd.Dir = dir
161		}
162		if len(gitOverrides) > 0 {
163			cmd.Env = gitConfigOverrideEnv(os.Environ(), gitOverrides)
164		}
165		stdout, err := cmd.StdoutPipe()
166		if err != nil {
167			return nil, err
168		}
169		stderr := &cappedBuffer{limit: streamStderrCap}
170		cmd.Stderr = stderr
171		if err := cmd.Start(); err != nil {
172			return nil, err
173		}
174		return &execStream{cmd: cmd, stdout: stdout, stderr: stderr}, nil
175	}
176	
177	type execStream struct {
178		cmd    *exec.Cmd
179		stdout io.ReadCloser
180		stderr *cappedBuffer
181	}
182	
183	func (s *execStream) Stdout() io.Reader { return s.stdout }
184	
185	func (s *execStream) Wait() ([]byte, error) {
186		err := s.cmd.Wait()
187		return s.stderr.Bytes(), err
188	}
189	
190	func (s *execStream) Close() error {
191		// cmd.Wait closes the stdout pipe; closing again is harmless and covers the
192		// case where the caller never reached Wait.
193		return s.stdout.Close()
194	}
195	
196	// cappedBuffer is an io.Writer that retains at most limit bytes. Writes past the
197	// cap are counted but discarded, so diagnostics keep the head of the output.
198	type cappedBuffer struct {
199		buf   bytes.Buffer
200		limit int
201	}
202	
203	func (c *cappedBuffer) Write(p []byte) (int, error) {
204		if room := c.limit - c.buf.Len(); room > 0 {
205			if room < len(p) {
206				c.buf.Write(p[:room])
207			} else {
208				c.buf.Write(p)
209			}
210		}
211		return len(p), nil
212	}
213	
214	func (c *cappedBuffer) Bytes() []byte { return c.buf.Bytes() }
